-- budget-plants-equestria (researched)
UPDATE businesses SET description = 'Budget Plants is a nursery on Stellenberg Road in Equestria, Pretoria, originally opened as R3 and R5 Nursery in 1999 before evolving into Budget Plants and Landscaping. It grows much of its own stock and sells flowers, plants, trees, seedlings, herbs, pots and gardening accessories, and hosts occasional gardening workshops covering topics such as gardening for birds without creating a pest problem.

The nursery has built up a loyal following over the years, with more than 12,000 followers on its Facebook page and around 90% of reviewers recommending it. Budget Plants is open Monday to Friday from 9am to 4pm and Saturdays from 9am to 3pm, giving customers a weekend window to shop for plants alongside weekday visits.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.facebook.com/R3andR5Nursery/'), description_enriched_at = datetime('now') WHERE slug = 'budget-plants-equestria' AND description = 'Budget Plants is a nursery on Stellenberg Road in Equestria, Pretoria, originally opened as R3 and R5 Nursery in 1999 before evolving into Budget Plants and Landscaping. It grows much of its own stock and sells flowers, plants, trees, seedlings, herbs, pots and gardening accessories, and hosts occasional gardening workshops.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- cadcon-steel-construction-engineering-doringkloof (researched)
UPDATE businesses SET description = 'Cadcon, trading as Cadcon Steel Construction & Engineering, is a privately owned structural steelwork company established in 1987 on a plot outside Pretoria, now based in Lyttelton Manor, Centurion. The firm specialises in structural steelwork solutions across the construction and engineering industries, with a monthly production capacity of around 600 tons.

Cadcon manages projects and structural steelwork using Fabtrol software, with 3D modelling and detail draughting carried out in TEKLA, and its scope covers the supply, fabrication and erection of both structural steelwork and platework, backed by its own blasting and painting facilities. The company is a member of the South African Institute of Steel Construction in good standing, and has worked on projects across South Africa and neighbouring countries over more than three decades.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.saisc.co.za/listing/cadcon/'), description_enriched_at = datetime('now') WHERE slug = 'cadcon-steel-construction-engineering-doringkloof' AND description = 'Cadcon (Pty) Ltd, trading as Cadcon Steel Construction & Engineering, is a structural steelwork company established in 1987 offering detailing, fabrication, corrosion protection and erection of structural steel and platework, with a monthly production capacity of around 600 tons, and has worked on projects across South Africa and neighbouring countries.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- cartridge-hyper-elardus-park-elardus-park (researched)
UPDATE businesses SET description = 'Cartridge Hyper Elardus Park stocks original-brand and generic or compatible inkjet and laser cartridges, toner, printheads, drum units and photoconductor units, and holds certified-retailer status for HP, Samsung, Canon, Lexmark, Epson, OKI and Brother, covering both branded consumables and the parts needed to keep an older printer running.

Rather than relying on the chain''s own store locator, this branch''s presence is independently confirmed through The Park Shopping Centre''s own tenant directory, which lists Cartridge Hyper among its current tenants under the same contact number, a confirmation that comes from the centre itself rather than the retailer describing its own footprint. Trading from The Park Shopping Centre at the corner of Delmas Road and Barnard Street in Elardus Park, Pretoria, the store serves households, offices and businesses needing printer cartridges, toner and related consumables, and is open Monday to Friday from 8am to 5:30pm and Saturdays from 9am to 2pm.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://cartridgehyper.co.za/store/cartridge.hyper.elardus.park'), description_enriched_at = datetime('now') WHERE slug = 'cartridge-hyper-elardus-park-elardus-park' AND description = 'Cartridge Hyper is a South African retail chain, established in 2003, specializing in original and generic inkjet and laser printer cartridges, toner, drum units and printheads for brands including HP, Canon, Samsung, Epson, Lexmark, Oki and Brother; this store is located at The Park Shopping Centre in Elardus Park, Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- ccl-global-annlin (researched)
UPDATE businesses SET description = 'CCL Global is a health and sports industry company based in Annlin Business Park, Pretoria, providing products and technology for injury prevention and recovery, and working with South African sports brands including the Springboks, Bulls, Lions and Stormers. The company''s name comes from the first letters of its directors'' three children''s names.

Alongside its product work, CCL Global focuses heavily on developing its own employees, promoting staff on merit rather than time served and providing ongoing training in both management and sales and marketing, in addition to the initial training most employers only give at the start of a job. The business is part of a group with branches in South Africa, Namibia, Taiwan and the United Kingdom, and its Annlin office is open on weekdays from 8am to 5pm.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.cclglobal.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'ccl-global-annlin' AND description = 'CCL Global is a health and sports industry company based in Annlin Business Park, Pretoria, providing products and technology for injury prevention and recovery, and working with South African sports brands including the Springboks, Bulls, Lions, and Stormers. The company also operates branches in Namibia, Taiwan, and the United Kingdom.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
